import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Tags from '@yaireo/tagify/dist/react.tagify';
import '@yaireo/tagify/dist/tagify.css';
import api from '../api';
import '../App.css';

function Home() {
  const [currentView, setCurrentView] = useState('welcome');
  const [predictions, setPredictions] = useState([]);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const navigate = useNavigate();

  const [profileData, setProfileData] = useState({
    cgpa: '', degree: '', yop: '', skills: ''
  });

  const [predictData, setPredictData] = useState({
    major: '', cgpa: '', degree: '', yop: '', skills: ''
  });

  const skillsWhitelist = ["Python","Communication","DataStructures","Algorithms","SQL","Java","C++","JavaScript","HTML","CSS","Git","Linux","Django","React","Matlab","Excel","Accounting","Financial Modeling","Electronics","Microcontrollers","RTOS","SolidWorks","AutoCAD","Lean Manufacturing","Thermodynamics","Mechanics","Materials","CAD","Valuation","M&A"];

  useEffect(() => {
    fetchProfile();
  }, []);

  const fetchProfile = async () => {
    try {
      const res = await api.get('/profile/latest');
      if (res.data.cgpa) {
        setProfileData({
          cgpa: res.data.cgpa,
          degree: res.data.degree,
          yop: res.data.year_of_graduation,
          skills: res.data.skills.join(',')
        });
      }
    } catch (err) {
      console.error(err);
    }
  };

  const handleProfileSubmit = async (e) => {
    e.preventDefault();
    try {
      await api.post('/profile/update', profileData);
      setIsEditingProfile(false);
      alert("Profile updated successfully!");
    } catch (err) {
      console.error(err);
    }
  };

  const handlePredictSubmit = async (e) => {
    e.preventDefault();
    setCurrentView('results');
    try {
      const res = await api.post('/predict/save', predictData);
      setPredictions(res.data.predictions || []);
    } catch (err) {
      console.error(err);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  return (
    <div>
      <div className="stars"></div>

      <div className="sidebar">
        <h1>Welcome Back!</h1>
        <button
          className={currentView === 'profile' ? 'active' : ''}
          onClick={() => setCurrentView('profile')}
        >
          <i className="fa-solid fa-user-gear"></i> Profile Info
        </button>
        <button
          className={currentView === 'predict' ? 'active' : ''}
          onClick={() => setCurrentView('predict')}
        >
          <i className="fa-solid fa-brain"></i> Predict
        </button>
        <button onClick={() => navigate('/archive')}>
          <i className="fa-solid fa-box-archive"></i> View Archive
        </button>
        <button onClick={handleLogout} style={{ marginTop: 'auto', marginBottom: '30px' }}>
          <i className="fa-solid fa-right-from-bracket"></i> Logout
        </button>
      </div>

      <main className="main-content">

        {currentView === 'welcome' && (
          <div id="welcome-screen">
            <h1 className="welcome-title">Hello, Explorer!</h1>
            <p className="welcome-subtitle">What would you like to do today?</p>
            <div className="quick-actions-container">
              <div className="quick-action-card" onClick={() => setCurrentView('profile')}>
                <i className="fa-solid fa-address-card" style={{ color: '#c084fc', fontSize: '2.5rem' }}></i>
                <h3>Update Profile</h3>
                <p style={{ color: '#a1a1aa' }}>Keep your details current for the best predictions.</p>
              </div>
              <div className="quick-action-card" onClick={() => setCurrentView('predict')}>
                <i className="fa-solid fa-wand-magic-sparkles" style={{ color: '#c084fc', fontSize: '2.5rem' }}></i>
                <h3>Get Prediction</h3>
                <p style={{ color: '#a1a1aa' }}>Discover your potential career paths right now.</p>
              </div>
            </div>
          </div>
        )}

        {currentView === 'profile' && (
          <form className="form-container" onSubmit={handleProfileSubmit}>
            <h2 style={{ color: '#fff', marginTop: 0 }}>Your Profile</h2>
            <label>CGPA</label>
            <input type="number" step="0.01" value={profileData.cgpa} onChange={(e) => setProfileData({...profileData, cgpa: e.target.value})} disabled={!isEditingProfile} required />
            <label>Degree</label>
            <input type="text" value={profileData.degree} onChange={(e) => setProfileData({...profileData, degree: e.target.value})} disabled={!isEditingProfile} required />
            <label>Skills</label>
            <div style={{ pointerEvents: isEditingProfile ? 'auto' : 'none' }}>
              <Tags
                settings={{ whitelist: skillsWhitelist }}
                value={profileData.skills}
                onChange={(e) => setProfileData({...profileData, skills: e.detail.value})}
              />
            </div>
            <label>Year of Graduation</label>
            <input type="number" value={profileData.yop} onChange={(e) => setProfileData({...profileData, yop: e.target.value})} disabled={!isEditingProfile} required />

            {isEditingProfile ? (
              <button type="submit" className="btn" style={{ background: 'linear-gradient(90deg, #4facfe, #00f2fe)' }}>Save Profile</button>
            ) : (
              <button type="button" className="btn" style={{ background: '#ffa500' }} onClick={() => setIsEditingProfile(true)}>Edit Profile</button>
            )}
          </form>
        )}

        {currentView === 'predict' && (
          <form className="form-container" onSubmit={handlePredictSubmit}>
            <h2 style={{ color: '#fff', marginTop: 0 }}>New Prediction</h2>
            <label>Major</label>
            <input type="text" value={predictData.major} onChange={(e) => setPredictData({...predictData, major: e.target.value})} required />
            <label>CGPA</label>
            <input type="number" step="0.01" value={predictData.cgpa} onChange={(e) => setPredictData({...predictData, cgpa: e.target.value})} required />
            <label>Degree</label>
            <input type="text" value={predictData.degree} onChange={(e) => setPredictData({...predictData, degree: e.target.value})} required />
            <label>Skills</label>
            <Tags
                settings={{ whitelist: skillsWhitelist }}
                onChange={(e) => setPredictData({...predictData, skills: e.detail.value})}
            />
            <label>Year of Graduation</label>
            <input type="number" value={predictData.yop} onChange={(e) => setPredictData({...predictData, yop: e.target.value})} required />
            <button type="submit" className="btn" style={{ background: 'linear-gradient(90deg, #4facfe, #00f2fe)' }}>Predict</button>
          </form>
        )}

        {currentView === 'results' && (
          <div id="predictionResultContainer">
            <h2 style={{ textAlign: 'center', background: 'linear-gradient(90deg, #4facfe, #00f2fe)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>✨ Your Predicted Career Paths</h2>
            <table id="predictionResultTable">
              <thead>
                <tr>
                  <th style={{ width: '30%' }}>Role</th>
                  <th style={{ width: '25%' }}>Confidence</th>
                  <th>Justification & Scope</th>
                </tr>
              </thead>
              <tbody>
                {predictions.length === 0 ? (
                  <tr><td colSpan="3" style={{ textAlign: 'center', color: '#fff' }}>🧠 Analyzing your profile...</td></tr>
                ) : (
                  predictions.map((pred, index) => (
                    <tr key={index}>
                      <td style={{ color: '#fff' }}><strong>{pred.role}</strong></td>
                      <td>
                        <div style={{ width: '100%', height: '20px', backgroundColor: '#333', borderRadius: '10px' }}>
                          <div style={{ width: pred.score, height: '100%', backgroundColor: parseFloat(pred.score) > 75 ? '#28a745' : parseFloat(pred.score) > 50 ? '#ffc107' : '#dc3545', borderRadius: '10px', textAlign: 'center', color: '#fff', fontSize: '0.8rem', lineHeight: '20px' }}>
                            {pred.score}
                          </div>
                        </div>
                      </td>
                      <td style={{ color: '#a1a1aa' }}>{pred.scope}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
            <button className="btn" style={{ marginTop: '20px', width: '200px' }} onClick={() => setCurrentView('predict')}>Make Another Prediction</button>
          </div>
        )}

      </main>
    </div>
  );
}

export default Home;
